const b = $json.body ?? $json;
const required = ['name','email','company'];
const missing = required.filter(k => !b[k] || String(b[k]).trim() === '');
const email = String(b.email ?? '').trim().toLowerCase();
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
return [{json:{lead_id:String(b.lead_id ?? `lead_${Date.now()}`),name:String(b.name ?? '').trim(),email,company:String(b.company ?? '').trim(),role:b.role ?? null,phone:b.phone ?? null,message:String(b.message ?? '').slice(0,4000),source:String(b.source ?? 'webhook'),consent_to_contact:Boolean(b.consent_to_contact),validation:{valid:missing.length===0 && validEmail,missing,valid_email:validEmail}}}];

const crypto = require('crypto');
const lead = $json;
const idempotencyKey = crypto.createHash('sha256').update(`${lead.email}|${lead.company}|${lead.source}`).digest('hex');
return [{json:{event_id:`evt_${crypto.randomUUID()}`,event_type:'lead.created',schema_version:'1.0',workflow_version:'1.0.0',correlation_id:`corr_${crypto.randomUUID()}`,idempotency_key:idempotencyKey,occurred_at:new Date().toISOString(),payload:lead,metadata:{orchestrator:'n8n',safe_starter:true}}}];
